import java.util.*;class RiverBroadCurveTest{static List<RiverRibbon.Point> path(){var p=new ArrayList<RiverRibbon.Point>();for(int x=100;x<=700;x+=8)p.add(new RiverRibbon.Point(x,300,4,90,100000));p.add(new RiverRibbon.Point(700,300,4,90,100000));for(int z=308;z<=900;z+=8)p.add(new RiverRibbon.Point(700,z,4,90,100000));return p;}public static void main(String[]args){int n=128;var flat=EnvironmentMap.filled(n*n,92);var curved=RiverMorphology.shape(path(),flat,n,8,83);double nearest=999,maxTurn=0;for(int i=0;i<curved.size();i++){var b=curved.get(i);nearest=Math.min(nearest,Math.hypot(b.x()-700,b.z()-300));if(i>0&&i+1<curved.size()){var a=curved.get(i-1);var c=curved.get(i+1);double ax=b.x()-a.x(),az=b.z()-a.z(),bx=c.x()-b.x(),bz=c.z()-b.z();if(Math.hypot(ax,az)>.01&&Math.hypot(bx,bz)>.01)maxTurn=Math.max(maxTurn,Math.abs(Math.atan2(ax*bz-az*bx,ax*bx+az*bz)));}}if(nearest<25||maxTurn>.15)throw new AssertionError("Corner remains tight: clearance="+nearest+" max turn="+maxTurn);var barrier=flat.clone();for(int z=0;z<n;z++)for(int x=0;x<n;x++)if(Math.hypot(x*8-650,z*8-350)<28)barrier[z*n+x]=180;var safe=RiverMorphology.shape(path(),barrier,n,8,83);for(int i=1;i<safe.size();i++){var a=safe.get(i-1);var b=safe.get(i);for(int j=0;j<=8;j++){var p=RiverRibbon.lerp(a,b,j/8.);if(RiverShape.height(barrier,n,p.x()/8,p.z()/8)>120)throw new AssertionError("Broad bend crossed protected hole");}}if(curved.get(0).x()!=100||Math.abs(curved.get(curved.size()-1).z()-900)>8)throw new AssertionError("Moved source/outlet");System.out.println("PASS: large bend rounds 90-degree corner with "+nearest+" block setback and maximum turn "+Math.toDegrees(maxTurn)+" degrees per sample; source/outlet and hole avoidance retained");}}
